    class ColumnRefused(
        
        val `detail`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class InvalidRecurrence(
        
        val `rule`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "rule=${ `rule` }"
    }
    
    /**
     * A Checkvist request the core refused to make, or an answer it could
     * not read (`checkvist.rs`).
     */
    class Checkvist(
        
        val `detail`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * An estimate or minimum block typed in minutes that does not read as
     * one (`editor_draft.rs`).
     */
    class InvalidEstimate(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    /**
     * A follow-up repeat outside 1 to 365 days (`waiting.rs`).
     */
    class InvalidFollowUpRepeat(
        
        val `days`: kotlin.UInt
        ) : CoreException() {
        override val message
            get() = "days=${ `days` }"
    }
    
    /**
     * A Google Calendar answer the core could not read
     * (`google_calendar.rs`).
     */
    class GoogleCalendar(
        
        val `detail`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<CoreException> {
        override fun lift(error_buf: RustBuffer.ByValue): CoreException = FfiConverterTypeCoreError.lift(error_buf)
    }

    
}

